-- 먼저 japanese.sql로 테이블을 생성하세요.
-- 아래 YOUR_USER_ID를 Supabase Authentication > Users의 본인 User UID로 바꾸고
-- Supabase SQL Editor에서 전체를 실행하세요. 재실행해도 같은 문장은 추가되지 않습니다.
begin;
do $import$
declare
  target_user_id uuid := '8716647f-9104-4d21-b9f4-6a33b1ea4685';
begin
  if not exists (select 1 from auth.users where id = target_user_id) then
    raise exception '등록할 사용자를 찾을 수 없습니다. User UID를 확인하세요.';
  end if;
  insert into public.little_plan_japanese (user_id, expression, reading, meaning)
  select target_user_id, phrase.expression, phrase.reading, phrase.meaning
  from (values
    (1, '結構前に、「山奥に家族構成っぽく置かれたマネキンが傷つけられてた」ってカキコミがあったと思うけど、それと似たような体験をした。', 'けっこうまえに、「やまおくにかぞくこうせいっぽくおかれたマネキンがきずつけられてた」ってカキコミがあったとおもうけど、それとにたようなたいけんをした。', '꽤 오래전에 산속에 가족처럼 배치된 마네킹이 훼손됐다는 게시글이 있었던 것 같은데, 비슷한 경험을 했다. 〜っぽく: ~처럼. 〜って: ~라고 하는 구어체 인용. カキコミ: 인터넷 게시글.'),
    (2, 'うちは田舎だから、シーズンになるとよく裏山にキノコ取りに行く。', 'うちはいなかだから、シーズンになるとよくうらやまにキノコとりにいく。', '우리 집은 시골이라 철이 되면 자주 뒷산에 버섯을 따러 간다. 〜になると: ~이 되면. 裏山: 뒷산.'),
    (3, '小学生の頃は、よく採れる場所をじいちゃんに教えてもらいながら２人で行ってたけど、中学生になると１人で行ったり、友達と行ったりしてた。', 'しょうがくせいのころは、よくとれるばしょをじいちゃんにおしえてもらいながらふたりでいってたけど、ちゅうがくせいになるとひとりでいったり、ともだちといったりしてた。', '초등학생 때는 할아버지에게 버섯이 잘 나는 곳을 배우며 둘이 다녔지만 중학생이 되자 혼자 또는 친구와 갔다. 〜てもらいながら: 도움을 받으면서. 〜たり〜たりする: ~하기도 하고 ~하기도 하다.'),
    (4, 'その日は日曜日だったから、友達と２人で行ったんだ。', 'そのひはにちようびだったから、ともだちとふたりでいったんだ。', '그날은 일요일이어서 친구와 둘이 갔어. 〜んだ: 상황이나 이유를 설명하는 친근한 말투.'),
    (5, '最初は順調にいろいろ採って、そろそろ帰ろうかとしてた時、友達がいきなり叫んで、その場にへたりこんだ。', 'さいしょはじゅんちょうにいろいろとって、そろそろかえろうかとしてたとき、ともだちがいきなりさけんで、そのばにへたりこんだ。', '처음에는 순조롭게 채집하다가 슬슬 돌아가려던 순간 친구가 갑자기 비명을 지르고 주저앉았다. いきなり: 갑자기. へたりこむ: 힘이 풀려 주저앉다.'),
    (6, 'その時は、木の枝で足を切ることがよくあるから、それかと思ったけど、友達は上を見てる。', 'そのときは、きのえだであしをきることがよくあるから、それかとおもったけど、ともだちはうえをみてる。', '그때는 나뭇가지에 다리를 베인 줄 알았는데 친구는 위를 보고 있었다. それかと思った: 그건가 싶었다. 見てる: 見ている의 축약.'),
    (7, 'だから俺もつられて上を見た。', 'だからおれもつられてうえをみた。', '그래서 나도 덩달아 위를 봤다. つられて: 다른 사람의 행동이나 감정에 이끌려 덩달아.'),
    (8, 'そこには首吊り死体。', 'そこにはくびつりしたい。', '거기에는 목을 맨 시체가 있었다. 首吊り: 목매달기. 명사로 문장을 끝내 긴장감을 주는 표현.'),
    (9, 'それも２体。', 'それもにたい。', '그것도 두 구나. それも: 그것도, 게다가. 体: 시체나 인형 등을 세는 단위.'),
    (10, '本当に驚いた時は声も出せない。', 'ほんとうにおどろいたときはこえもだせない。', '정말 놀라면 목소리조차 나오지 않는다. 声も出せない: 말이나 비명조차 나오지 않다.'),
    (11, '俺は後ずさって何も出来ないままパニックになってたんだが、しばらく見てる内に、死体はホンモノではなくマネキンだと気づいた。', 'おれはあとずさってなにもできないままパニックになってたんだが、しばらくみてるうちに、したいはホンモノではなくマネキンだときづいた。', '나는 뒷걸음질 치며 패닉에 빠졌지만 한동안 보다가 시체가 아닌 마네킹이라는 걸 깨달았다. 〜ないまま: ~하지 못한 채. 〜てるうちに: ~하는 사이에. 気づく: 알아차리다.'),
    (12, 'イタズラにしてはタチが悪いだろ！と毒づきながら友達と下山して、うちで親父に説明し、脚立と手斧、枝切りハサミを持って３人でマネキンを片付けに行った。', 'イタズラにしてはタチがわるいだろ！とどくづきながらともだちとげざんして、うちでおやじにせつめいし、きゃたつとておの、えだきりハサミをもってさんにんでマネキンをかたづけにいった。', '장난치고는 악질적이라고 욕하며 하산한 뒤 아버지와 함께 마네킹을 치우러 갔다. 〜にしては: ~치고는. タチが悪い: 질이 나쁘다. 毒づく: 욕설을 내뱉다.'),
    (13, '親父が脚立に上り、俺と友達は脚立を支えた。', 'おやじがきゃたつにのぼり、おれとともだちはきゃたつをささえた。', '아버지가 사다리에 올라가고 나와 친구는 사다리를 받쳤다. 脚立: 접이식 사다리. 支える: 받치다, 지탱하다.'),
    (14, '親父は手際良くマネキンの首のロープを切って下に落とし、こんなものはさっさと捨てようと、３人でうちの納屋に運んだんだ。', 'おやじはてぎわよくマネキンのくびのロープをきってしたにおとし、こんなものはさっさとすてようと、さんにんでうちのなやにはこんだんだ。', '아버지는 능숙하게 밧줄을 잘라 마네킹을 내리고 얼른 버리자며 헛간으로 옮겼다. 手際良く: 능숙하게. さっさと: 얼른. 納屋: 헛간.'),
    (15, 'でも、そのままだとまた誤解を受けるだろうからって、なるべく人型ってことが分からないようにバラバラに砕いてから捨てようということになって、マネキンが着てた粗末な服を剥いだんだ。', 'でも、そのままだとまたごかいをうけるだろうからって、なるべくひとがたってことがわからないようにバラバラにくだいてからすてようということになって、マネキンがきてたそまつなふくをはいだんだ。', '그대로 버리면 오해받을 수 있어 사람 형태를 알아보지 못하도록 부수기로 하고 옷을 벗겼다. なるべく: 가능한 한. 〜ように: ~하도록. 〜ことになって: ~하기로 결정되어. 剥ぐ: 벗겨내다.'),
    (16, 'そうしたら、マネキンの腹に赤ペンキで大きく書いてあった。', 'そうしたら、マネキンのはらにあかペンキでおおきくかいてあった。', '그러자 마네킹의 배에 빨간 페인트로 크게 글씨가 적혀 있었다. そうしたら: 그랬더니. 〜てあった: 누군가 해 놓은 결과가 남아 있는 상태.'),
    (17, 'このマネキンを下ろした人間は死ぬ。', 'このマネキンをおろしたにんげんはしぬ。', '이 마네킹을 내린 인간은 죽는다. 下ろす: 높은 곳에서 아래로 내리다. 死ぬ: 죽다.'),
    (18, 'それを見て、その場にいた全員が凍りついた。', 'それをみて、そのばにいたぜんいんがこおりついた。', '그걸 보고 그 자리에 있던 모두가 얼어붙었다. 凍りつく: 공포나 충격으로 몸이 굳다.'),
    (19, 'でも親父がもう一体の、女物のワンピースを着せられたマネキンの服を剥いだら、やっぱりその腹にも書いてあった。', 'でもおやじがもういったいの、おんなもののワンピースをきせられたマネキンのふくをはいだら、やっぱりそのはらにもかいてあった。', '아버지가 여성용 원피스를 입힌 다른 마네킹의 옷을 벗기자 역시 배에 글씨가 있었다. 女物: 여성용. 着せられた: 입혀진. やっぱり: 역시.'),
    (20, 'このマネキンを下ろした人間の、最も愛する者が死ぬ。', 'このマネキンをおろしたにんげんの、もっともあいするものがしぬ。', '이 마네킹을 내린 인간이 가장 사랑하는 사람이 죽는다. 最も: 가장. 愛する者: 사랑하는 사람.'),
    (21, '親父は、凍り付いてる俺と友達を宥めながら「ジュースでも買ってこい」と言って納屋から出し、その間、そのマネキン２体をバラバラに砕いて捨てた。', 'おやじは、こおりついてるおれとともだちをなだめながら「ジュースでもかってこい」といってなやからだし、そのあいだ、そのマネキンにたいをバラバラにくだいてすてた。', '아버지는 얼어붙은 우리를 달래며 주스를 사 오라고 내보낸 뒤 마네킹 두 개를 부숴 버렸다. 宥める: 달래다. 買ってこい: 사 와라(명령형). その間: 그동안.'),
    (22, 'それ以来、俺と友達と親父の間ではそのことはタブーになっている。', 'それいらい、おれとともだちとおやじのあいだではそのことはタブーになっている。', '그 이후로 나와 친구, 아버지 사이에서 그 일은 금기가 되었다. それ以来: 그 이후 줄곧. 〜の間では: ~사이에서는.'),
    (23, '口に出すのも嫌だからここに書くけど、「最も愛する者が死ぬ」と書かれたことが一番辛い。', 'くちにだすのもいやだからここにかくけど、「もっともあいするものがしぬ」とかかれたことがいちばんつらい。', '입 밖에 내는 것조차 싫어서 여기에 쓰지만 가장 사랑하는 사람이 죽는다는 글이 제일 괴롭다. 口に出す: 입 밖으로 내다. 辛い: 마음이 괴롭다.')
  ) as phrase(position, expression, reading, meaning)
  where not exists (
    select 1 from public.little_plan_japanese existing
    where existing.user_id = target_user_id and existing.expression = phrase.expression
  )
  order by phrase.position;
end
$import$;
commit;
